function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 3 || nums.length > 100) return 'nums needs 3 to 100 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each value is an integer between 1 and 100.';
  return null;
}

