function countHillValley(nums) {
  let count = 0;
  let left = nums[0];

  for (let i = 1; i < nums.length - 1; i++) {
    if (nums[i] === nums[i + 1]) {
      continue;
    }
    const isHill = nums[i] > left && nums[i] > nums[i + 1];
    const isValley = nums[i] < left && nums[i] < nums[i + 1];
    if (isHill || isValley) {
      count++;
    }
    left = nums[i];
  }
  return count;
}

