function countHillValley(nums) {
  // Apply the definition at every index, counting each block of equal values at its first index only.
  let total = 0;
  for (let i = 0; i < nums.length; i++) {
    if (i > 0 && nums[i - 1] === nums[i]) continue;
    let l = i - 1;
    while (l >= 0 && nums[l] === nums[i]) l--;
    let r = i + 1;
    while (r < nums.length && nums[r] === nums[i]) r++;
    if (l < 0 || r >= nums.length) continue;
    if ((nums[l] < nums[i] && nums[r] < nums[i]) || (nums[l] > nums[i] && nums[r] > nums[i])) total++;
  }
  return total;
}

