function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(90, 100) : int(3, 10);
  const top = rand() < 0.6 ? int(1, 4) : 100;
  const nums = [int(1, top)];
  while (nums.length < n) {
    // Repeat the previous value often so that flat stretches appear.
    nums.push(rand() < 0.3 ? nums[nums.length - 1] : int(1, top));
  }
  return [nums];
}
